<?php
use DigiForge\PortalAccess\{Panel,Store,Session,Owner,EmailAuthentication};
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class Presentation14Test extends WP_UnitTestCase {
 protected function setUp():void{parent::setUp();PortalAccessFixture::reset();$_GET=['df_view'=>'users','df_shop'=>'digital'];}
 protected function tearDown():void{global $wpdb;$_GET=[];$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');parent::tearDown();}
 private function stale():void{$m=WP_Session_Tokens::get_instance(1);$t=wp_get_session_token();$s=$m->get($t);$s['digiforge_email_verified_at']=time()-600;$m->update($t,$s);}
 public function testStaleProofHasExplicitStepUpAndExactSafeShopContinuation():void {
  PortalAccessFixture::enroll();$before=Store::read(1);$this->stale();self::assertFalse(EmailAuthentication::recent(1));self::assertSame('digiforge_portal_fresh_email_required',Owner::require('digital')->get_error_code());$h=Panel::render();self::assertStringContainsString('Fresh email verification required',$h);self::assertStringNotContainsString('enrollment is required',$h);self::assertStringNotContainsString('Prepare private invitation',$h);
  preg_match('/href="([^"]+)"/',$h,$m);$q=[];parse_str(wp_parse_url(html_entity_decode($m[1],ENT_QUOTES),PHP_URL_QUERY),$q);self::assertSame('login',$q['df_auth']);self::assertSame(home_url('/'),strtok($q['redirect_to'],'?'));$return=[];parse_str(wp_parse_url($q['redirect_to'],PHP_URL_QUERY),$return);self::assertSame(['df_view'=>'users','df_shop'=>'digital'],$return);self::assertSame($before,Store::read(1));
 }
 public function testFreshProofRendersManagementAndStaleCannotWrite():void{PortalAccessFixture::enroll();self::assertStringContainsString('Prepare private invitation',Panel::render());$this->stale();$id=self::factory()->user->create(['role'=>'administrator']);self::assertWPError(Store::change($id,'Viewer',['digital'=>['research']],true,0,wp_generate_uuid4()));self::assertNull(Store::read($id));}
 public function testInvalidOwnerDoesNotMasqueradeAsStepUp():void{PortalAccessFixture::owner();$h=Panel::render();self::assertStringNotContainsString('Fresh email verification required',$h);self::assertStringContainsString('enrollment is required',$h);}
 public function testRevokedOwnerDoesNotMasqueradeAsStepUp():void{PortalAccessFixture::enroll();self::assertNotWPError(DigiForge\PortalAccess\OwnerBootstrap::revoke(wp_generate_uuid4()));$this->stale();self::assertNotSame('digiforge_portal_fresh_email_required',Owner::require('digital')->get_error_code());self::assertStringNotContainsString('Fresh email verification required',Panel::render());}
 public function testMissingSessionNeverShowsProtectedManagement():void{PortalAccessFixture::enroll();unset($_COOKIE[Session::name()]);$h=Panel::render();self::assertStringNotContainsString('Prepare private invitation',$h);self::assertStringContainsString('session is missing or expired',$h);}
 public function testSchedulerEvidenceIsBoundedAndMalformedValuesAreNotEchoed():void {
  $r=new DigiForge\Portal\SchedulerDependencyPanel();$h=$r->render(['action_scheduler_dependency'=>['state'=>'AVAILABLE','version'=>'4.2.0','registered_version'=>'4.2.0','minimum_version'=>'3.5.0','maximum_major_exclusive'=>5]]);foreach(['AVAILABLE','4.2.0','3.5.0','Loaded version','Registered version','API compatibility']as $label)self::assertStringContainsString($label,$h);
  foreach([null,[],['action_scheduler_dependency'=>null],['action_scheduler_dependency'=>['state'=>'AVAILABLE','version'=>[]]],['action_scheduler_dependency'=>['state'=>'AVAILABLE','version'=>'4.2.0','registered_version'=>'3.5.0','minimum_version'=>'3.5.0','maximum_major_exclusive'=>5]],['action_scheduler_dependency'=>['state'=>'<script>','version'=>['secret'],'registered_version'=>str_repeat('x',500),'minimum_version'=>'javascript:','maximum_major_exclusive'=>-1]]]as $bad){$h=$r->render($bad);self::assertStringContainsString('UNAVAILABLE',$h);self::assertStringNotContainsString('<script>',$h);self::assertStringNotContainsString('javascript:',$h);self::assertStringNotContainsString('secret',$h);}
 }
 public function testActualAutomationRendererDisplaysDependencyAndSeparateQueryEvidence():void{PortalAccessFixture::enroll();$m=new ReflectionMethod(DigiForge\Portal\Portal::class,'automationOperations');$m->setAccessible(true);ob_start();$m->invoke(new DigiForge\Portal\Portal());$h=ob_get_clean();foreach(['Action Scheduler dependency state','Classified state','Loaded version','Registered version','API compatibility boundary','Action Scheduler evidence','WP cron evidence']as $label)self::assertStringContainsString($label,$h);}
}
